{
  "propositions": [
    {
      "id": "P1",
      "proposition": "The new section defines \"early warning signs\" as evidence of a student's safety, health, or behavioral issues, including but not limited to engaging in or being a victim of harassment, intimidation, bullying, or cyber-bullying; making or receiving threats of violence; and signs of substance abuse, mental health issues, self-harm, or suicidal ideation.",
      "importance": "supporting",
      "section": "SECTION 1(b)",
      "source_quote": "\"early warning signs\" means evidence of a student's"
    },
    {
      "id": "P2",
      "proposition": "Each LEA and public charter school must implement a computer-based system that teachers and school staff must use to enter data on early warning signs demonstrated by enrolled students.",
      "importance": "core",
      "section": "SECTION 1(c)",
      "source_quote": "system that teachers and school staff must use to input data of early warning signs"
    },
    {
      "id": "P3",
      "proposition": "Each LEA and public charter school must ensure that every teacher and school staff member is trained to identify early warning signs and enter data into the computer-based system.",
      "importance": "supporting",
      "section": "SECTION 1(c)",
      "source_quote": "public charter school shall ensure that each teacher and school staff member is trained"
    },
    {
      "id": "P4",
      "proposition": "The computer-based system must align with § 49-6-4503, the School Discipline Act in Title 49, Chapter 6, Part 41, and the LEA's or public charter school's school safety plans adopted under the Schools Against Violence in Education (SAVE) Act in Part 8.",
      "importance": "supporting",
      "section": "SECTION 1(d)(1)",
      "source_quote": "(1) Align with the requirements in § 49-6-4503; the School Discipline Act,"
    },
    {
      "id": "P5",
      "proposition": "The computer-based system must include a database capable of receiving and maintaining student data entered by teachers and school staff about students' early warning signs.",
      "importance": "supporting",
      "section": "SECTION 1(d)(2)",
      "source_quote": "(2) Include a database that is capable of receiving and maintaining"
    },
    {
      "id": "P6",
      "proposition": "When an early warning sign is entered for a student, the computer-based system must immediately notify the LEA's or public charter school's personnel serving on its threat assessment team created under § 49-6-2701.",
      "importance": "core",
      "section": "SECTION 1(d)(3)",
      "source_quote": "(3) Immediately notify the LEA's or public charter school's personnel"
    },
    {
      "id": "P7",
      "proposition": "LEA or public charter school personnel receiving an early-warning-sign notification must review it and any previously received notifications about the student and determine whether further action is needed to address the student's behavior.",
      "importance": "core",
      "section": "SECTION 1(e)",
      "source_quote": "notification, and any notifications of the student previously received, and determine"
    },
    {
      "id": "P8",
      "proposition": "Each LEA and public charter school must annually report to the department of education, summarizing data collected in the immediately preceding school year and any interventions provided.",
      "importance": "core",
      "section": "SECTION 1(f)",
      "source_quote": "(f) Each LEA and public charter school shall annually submit a report to the"
    },
    {
      "id": "P9",
      "proposition": "Reports under the new section must comply with FERPA, 20 U.S.C. § 1232g; § 10-7-504; the Data Accessibility, Transparency, and Accountability Act in Title 49, Chapter 1, Part 7; and all other relevant privacy laws.",
      "importance": "supporting",
      "section": "SECTION 1(g)",
      "source_quote": "(g) Reports made pursuant to this section must comply with the Family"
    },
    {
      "id": "P10",
      "proposition": "If the commissioner of education finds an LEA or public charter school out of compliance with the new section, the commissioner may withhold state funds in an amount the commissioner determines until the LEA or school complies.",
      "importance": "core",
      "section": "SECTION 1(h)",
      "source_quote": "then the commissioner may withhold state funds, in an"
    },
    {
      "id": "P11",
      "proposition": "Section 49-6-2701 is amended to add \"and public charter school\" after \"Each LEA\" and \"or public charter school\" after \"LEA\" wherever it appears; add \"or public charter school's\" after \"LEA's\" in subsection (b); and add \"or public charter school governing body\" after \"local board of education\" and \"or the director of the public charter school\" after \"the director of schools\" in subsection (e).",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "\"and public charter school\" after \"Each LEA\", adding \"or public charter school\" after \"LEA\""
    },
    {
      "id": "P12",
      "proposition": "Section 49-6-2702(b) is amended to add \"or public charter school\" after \"LEA\" and \"or public charter school's\" after \"LEA's\".",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "\"or public charter school\" after \"LEA\" and adding \"or public charter school's\" after \"LEA's\"."
    },
    {
      "id": "P13",
      "proposition": "The act takes effect July 1, 2025.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "This act takes effect July 1, 2025, the public welfare requiring it."
    }
  ]
}
